<script setup lang="ts">
import {ref,watch} from 'vue';
import {ElMessageBox} from 'element-plus';
import {api} from '../api';import {useUI} from '../store';
interface Policy {retention_days:number;automatic_enabled:boolean;version:number}
interface Preview {preview_token:string;expires_at:number;retention_days:number;cutoff_at:number;eligible_reports:number;eligible_rows:number;protected_reports:number;batch_reports:number;batch_rows:number;affected_devices:number;affected_accounts:number;oldest_at:number|null;newest_at:number|null}
const ui=useUI(),policy=ref<Policy|null>(null),days=ref(90),automatic=ref(false),preview=ref<Preview|null>(null),busy=ref(false),error=ref(''),notice=ref('');
/** 功能：格式化服务端秒时间；参数：seconds；返回值：本机时区日期或占位。 */
function date(seconds:number|null){return seconds===null?'—':new Date(seconds*1000).toLocaleString();}
/** 功能：要求管理授权；参数：无；返回值：是否已授权。 */
function authorized(){if(ui.authorized)return true;ui.authOpen=true;return false;}
/** 功能：加载保留策略并清空旧预览；参数：无；返回值：异步完成。 */
async function load(){if(!authorized())return;busy.value=true;error.value='';notice.value='';preview.value=null;try{const r=await api.mutate<{policy:Policy}>('/api/history-cleanup/policy',{});policy.value=r.policy;days.value=r.policy.retention_days;automatic.value=r.policy.automatic_enabled;}catch(e){error.value=e instanceof Error?e.message:'读取失败';}finally{busy.value=false;}}
/** 功能：显式保存保留策略，首次开启自动清理时额外确认；参数：无；返回值：异步完成。 */
async function save(){if(busy.value||!policy.value||!authorized())return;busy.value=true;error.value='';notice.value='';preview.value=null;try{if(automatic.value&&!policy.value.automatic_enabled)await ElMessageBox.confirm('启用后服务启动及每6小时会按保留期限自动删除历史，每轮最多200份报告。账号与设备最新完整报告受保护。是否启用？','启用自动清理',{confirmButtonText:'启用自动清理',cancelButtonText:'取消',type:'warning'});const r=await api.mutate<{policy:Policy}>('/api/history-cleanup/save',{retention_days:days.value,automatic_enabled:automatic.value,version:policy.value.version});policy.value=r.policy;notice.value='保留策略已保存；本次保存不立即执行删除。';}catch(e){if(e instanceof Error)error.value=e.message;}finally{busy.value=false;}}
/** 功能：只读预览当前天数对应的删除批次，不保存策略或删除数据；参数：无；返回值：异步完成。 */
async function inspect(){if(busy.value||!authorized())return;busy.value=true;error.value='';notice.value='';preview.value=null;try{preview.value=await api.mutate<Preview>('/api/history-cleanup/preview',{retention_days:days.value});}catch(e){error.value=e instanceof Error?e.message:'预览失败';}finally{busy.value=false;}}
/** 功能：管理员输入确认文本后仅执行已预览的一批，清空凭证防止自动重试；参数：无；返回值：实际结果。 */
async function execute(){if(busy.value||!preview.value||!preview.value.batch_reports||!authorized())return;busy.value=true;error.value='';notice.value='';const plan=preview.value;try{await ElMessageBox.prompt(`将删除本批 ${plan.batch_reports} 份报告、${plan.batch_rows} 条窗口记录，不可撤销。请输入“删除历史额度”。`,'确认清理历史额度',{confirmButtonText:'确认删除本批历史',cancelButtonText:'取消',inputPattern:/^删除历史额度$/,inputErrorMessage:'请输入：删除历史额度',type:'warning'});preview.value=null;const r=await api.mutate<{deleted_reports:number;deleted_rows:number;remaining_reports:number}>('/api/history-cleanup/execute',{preview_token:plan.preview_token,confirmation:'删除历史额度'});notice.value=`已删除 ${r.deleted_reports} 份完整报告、${r.deleted_rows} 条窗口记录。剩余可清理 ${r.remaining_reports} 份；继续操作须重新预览。`; }catch(e){if(e instanceof Error){error.value=e.message;preview.value=null;}}finally{busy.value=false;}}
// 修改条件或失去授权后，旧预览不可继续使用；不把管理状态存入浏览器持久存储。
watch([days,automatic],()=>{preview.value=null;notice.value='';});
watch(()=>ui.authorized,value=>{if(!value){policy.value=null;preview.value=null;error.value='';notice.value='';}});
</script>
<template><section class="panel" style="margin-top:20px"><div class="panel-head"><span class="panel-title">历史额度清理</span><el-button :loading="busy" @click="load">{{ui.authorized?'读取保留策略':'管理授权'}}</el-button></div><div class="panel-body"><p>仅清理额度历史。始终保留账号及设备最新完整报告和有效回退报告，不修改账号映射、设备 ID、令牌或配置。每批最多200份报告。</p><template v-if="policy"><div class="setting-row"><div><b>保留期限</b><p>预览使用当前天数；保存后用于自动清理。</p></div><el-input-number v-model="days" :min="1" :max="3650" :precision="0" :disabled="busy"/><span>天</span></div><div class="setting-row"><div><b>自动清理</b><p>默认关闭；明确启用后在服务启动及每6小时运行一批。</p></div><el-switch v-model="automatic" :disabled="busy"/></div><el-button :loading="busy" @click="save">保存保留策略</el-button><el-button type="primary" :loading="busy" @click="inspect">仅预览，不删除</el-button><div v-if="preview" style="margin-top:16px"><p>截止时间：{{date(preview.cutoff_at)}}；预览有效至：{{date(preview.expires_at)}}。</p><p>可清理 {{preview.eligible_reports}} 份报告 / {{preview.eligible_rows}} 条窗口记录；受保护 {{preview.protected_reports}} 份完整报告。</p><p>本批 {{preview.batch_reports}} 份报告 / {{preview.batch_rows}} 条窗口记录，涉及 {{preview.affected_accounts}} 个账号、{{preview.affected_devices}} 台设备。</p><p>本批上报时间：{{date(preview.oldest_at)}} ～ {{date(preview.newest_at)}}。</p><el-button type="danger" :disabled="busy||!preview.batch_reports" @click="execute">管理员确认并清理本批</el-button></div></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/><p>不备份历史数据，删除后无法撤销；不会立即压缩数据库文件。只预览不会执行删除。</p></div></section></template>
